import {UI} from '../shared/copy.js';import {esc,getLang} from '../shared/core.js';import {readState} from '../shared/state.js';
const lang=getLang(),t=UI[lang],table=Math.min(999,Math.max(1,parseInt(new URLSearchParams(location.search).get('table'),10)||3));document.documentElement.lang=lang;document.querySelector('#controls').innerHTML=`<button class="primary" id="print">${esc(t.printQr)}</button><a class="secondary" href="owner.html?lang=${lang}#storeSetup">${esc(t.back)}</a>`;const url=new URL(`./?lang=${lang}&table=${table}`,location.href).href;const code=qrcode(0,'M');code.addData(url);code.make();document.querySelector('#paper').innerHTML=`<img class="logo" src="assets/brand.png" alt="주모 Jumo"><h3>${esc(readState().store.name)}</h3><p>${esc(t.table)} ${String(table).padStart(2,'0')}</p><div class="qr-code">${code.createSvgTag({cellSize:5,margin:4,scalable:true})}</div><p>${esc(t.menu)} · ${esc(t.chat)}</p><p>${esc(t.chooseLanguage)}</p><small>${esc(t.qrNote)}</small><small>${esc(t.demoNote)}</small><p class="modu-brand">modu ai <span>모두의 AI</span></p>`;document.querySelector('#print').addEventListener('click',()=>window.print());
